{"command":"POD=$(kubectl get pod -n egress -l app=app -o jsonpath='{.items[0].metadata.name}'); echo "pod=$POD";
echo "=== HTTP http://dep via service name (TCP 80) ==="; kubectl exec -n egress $POD -- sh -c 'wget -qO- --timeout=8 http://dep 2>&1 | head -5' | grep -i '^HTTP'; echo "exit=$?";
echo "=== HTTP http://192.168.46.68/ (dep pod IP) ==="; kubectl exec -n egress $POD -- sh -c 'wget -qO- --timeout=8 http://192.168.46.68/ 2>&1 | head -5' | grep -iE '(\<HTML>|Welcome to Nginx)' ; echo "exit=$?";
echo "=== http://other (should fail) ==="; kubectl exec -n egress $POD -- sh -c 'wget -qO- --timeout=8 http://other 2>&1 | head -5' | grep -iE "HTTP|Welcome to Nginx"; echo "exit=$?";
echo "=== DNS reverse check other ==="; kubectl exec -n egress $POD -- sh -c 'nslookup other 2>&1 | grep -Ei "SERVFAIL|NXDOMAIN"'; echo "exit=$?"; echo "=== DNS other IP ==="; kubectl exec -n egress $POD -- sh -c 'nslookup 10.96.253.65 2>&1 | grep -i "SERVFAIL|NXDOMAIN"'; echo "exit=$?""}

